<script lang="ts">let { data, form } = $props();
  const format = (date: Date) => new Intl.DateTimeFormat('en-PH', { dateStyle: 'full', timeStyle: 'short', timeZone: 'Asia/Manila' }).format(new Date(date));
</script>
<svelte:head><title>{data.event.title} | CS Week</title></svelte:head>
<a href="/events">← All events</a><h1>{data.event.title}</h1><p>{format(data.event.startAt)}</p><p>{data.event.description ?? 'More details coming soon.'}</p><p>{data.event.capacity === null ? 'No capacity limit' : `${data.event.capacity} participant capacity`}</p>
{#if form?.success}<p role="status">You’re registered! Check your dashboard or email for event updates.</p>{:else if data.event.status !== 'open'}<p>This event is not accepting registrations.</p>{:else}<h2>Register</h2><form method="POST" action="?/register">{#each data.fields as field}<label>{field.label}{#if field.fieldType === 'checkbox'} <input name={field.fieldKey} type="checkbox" />{:else if field.fieldType === 'select'} <select name={field.fieldKey} required={field.isRequired}><option value="">Choose one</option>{#each (field.options as string[] ?? []) as option}<option>{option}</option>{/each}</select>{:else}<input name={field.fieldKey} type={field.fieldType} required={field.isRequired} />{/if}</label>{/each}{#if form?.error}<p role="alert">{form.error}</p>{/if}<button>Register for free</button></form>{/if}
